'use strict';

const log = require('../lib/log');
const { buildChargePayload } = require('./gateway/payload');

// Charges an open invoice on the customer's saved card and marks it paid.
async function chargeInvoice(invoice, { customers, gateway, audit }) {
  if (invoice.status !== 'open') throw new Error(`Invoice ${invoice.number} is ${invoice.status}`);
  const customer = await customers.get(invoice.customerId);
  if (!customer || !customer.gatewayId) throw new Error(`No card on file for ${invoice.customerId}`);

  const payload = buildChargePayload(invoice, customer);
  const charge = await gateway.createCharge(payload);
  log.info('invoice charged', { invoice: invoice.number, charge: charge.id });

  if (audit) await audit.record('invoice.charged', { invoiceId: invoice.id, chargeId: charge.id, amount: payload.amount });
  return { ...invoice, status: 'paid', chargeId: charge.id };
}

module.exports = { chargeInvoice };
'use strict';

const { toMinor } = require('../../lib/money/minor');
const { toGatewayCurrency } = require('../../lib/currency/normalize');

// Body of POST /v1/charges on the card gateway.
function buildChargePayload(invoice, customer) {
  const currency = toGatewayCurrency(invoice.currency);
  return {
    amount: toMinor(invoice.total, currency),
    currency,
    customer: customer.gatewayId,
    description: `Invoice ${invoice.number}`,
    metadata: { invoice_id: invoice.id },
    idempotency_key: `inv_${invoice.id}`,
  };
}

module.exports = { buildChargePayload };
'use strict';

const https = require('https');
const log = require('../../lib/log');

// Thin client for the card gateway. Tests pass a fake with the same createCharge().
function createClient({ host = 'api.cardgateway.example', apiKey } = {}) {
  function post(pathname, body, idempotencyKey) {
    return new Promise((resolve, reject) => {
      const data = JSON.stringify(body);
      const req = https.request({
        host,
        path: pathname,
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          authorization: `Bearer ${apiKey}`,
          'idempotency-key': idempotencyKey,
        },
      }, (res) => {
        let raw = '';
        res.on('data', (d) => { raw += d; });
        res.on('end', () => {
          const parsed = raw ? JSON.parse(raw) : {};
          if (res.statusCode >= 400) return reject(new Error(`gateway ${res.statusCode}: ${parsed.error || raw}`));
          resolve(parsed);
        });
      });
      req.on('error', reject);
      req.end(data);
    });
  }

  return {
    async createCharge(payload) {
      log.info('gateway charge', { amount: payload.amount, currency: payload.currency });
      const { idempotency_key: key, ...body } = payload;
      return post('/v1/charges', body, key);
    },
  };
}

module.exports = { createClient };
'use strict';

const { exponent } = require('../currency/registry');

// Major units (12.5 dollars, 1500 yen) to integer minor units (1250 cents, 1500 yen).
function toMinor(amount, currency) {
  const n = Number(amount);
  if (!Number.isFinite(n)) throw new Error(`Invalid amount: ${amount}`);
  return Math.round(n * 10 ** exponent(currency));
}

function fromMinor(minor, currency) {
  return minor / 10 ** exponent(currency);
}

// Round a major-unit amount to what the currency can represent.
function roundMajor(amount, currency) {
  return fromMinor(toMinor(amount, currency), currency);
}

module.exports = { toMinor, fromMinor, roundMajor };
'use strict';

// The card gateway and the CRM take lower-case ISO codes ("usd", "jpy").
function toGatewayCurrency(code) {
  return String(code).trim().toLowerCase();
}

// Codes coming back from the gateway or typed by staff.
function fromExternalCurrency(code) {
  return String(code).trim().toUpperCase();
}

module.exports = { toGatewayCurrency, fromExternalCurrency };
'use strict';

// ISO 4217 currencies we bill in, with their minor-unit exponent.
// Codes are upper-case, as stored on invoices and plans.
const CURRENCIES = {
  USD: { exponent: 2, symbol: '$' },
  EUR: { exponent: 2, symbol: '€' },
  GBP: { exponent: 2, symbol: '£' },
  CHF: { exponent: 2, symbol: 'CHF' },
  AUD: { exponent: 2, symbol: 'A$' },
  SGD: { exponent: 2, symbol: 'S$' },
  JPY: { exponent: 0, symbol: '¥' },
  KRW: { exponent: 0, symbol: '₩' },
  VND: { exponent: 0, symbol: '₫' },
  CLP: { exponent: 0, symbol: 'CLP$' },
  BHD: { exponent: 3, symbol: 'BD' },
  KWD: { exponent: 3, symbol: 'KD' },
};

const DEFAULT_EXPONENT = 2;

function exponent(code) {
  const c = CURRENCIES[code];
  return c ? c.exponent : DEFAULT_EXPONENT;
}

function isSupported(code) {
  return Object.prototype.hasOwnProperty.call(CURRENCIES, code);
}

function symbol(code) {
  return CURRENCIES[code] ? CURRENCIES[code].symbol : code;
}

module.exports = { exponent, isSupported, symbol, DEFAULT_EXPONENT };
'use strict';

// Pre-2024 helper, kept for the revenue ledger, which is always in USD.
function toCents(amount) {
  return Math.round(Number(amount) * 100);
}

module.exports = { toCents };
const assert = require('assert');
const { buildChargePayload } = require('../src/payments/gateway/payload');

const customer = { gatewayId: 'cus_1' };

test('USD invoice is charged in cents', () => {
  const p = buildChargePayload({ id: 'i1', number: 'INV-1', currency: 'USD', total: 12.5 }, customer);
  assert.strictEqual(p.amount, 1250);
  assert.strictEqual(p.currency, 'usd');
});

test('EUR invoice is charged in cents', () => {
  const p = buildChargePayload({ id: 'i2', number: 'INV-2', currency: 'EUR', total: 99.99 }, customer);
  assert.strictEqual(p.amount, 9999);
  assert.strictEqual(p.idempotency_key, 'inv_i2');
});
// Minimal test runner (no dependencies): `node test/run.js` runs every test/*.test.js.
// Tests may be async; each gets 5 s before it counts as hung.
const fs = require('fs');
const path = require('path');

const TIMEOUT_MS = 5000;
const tests = [];
global.test = (name, fn) => tests.push({ name, fn });
for (const f of fs.readdirSync(__dirname).filter((x) => x.endsWith('.test.js')).sort()) {
  require(path.join(__dirname, f));
}

function withTimeout(promise) {
  let timer;
  const timeout = new Promise((_, reject) => { timer = setTimeout(() => reject(new Error(`timed out after ${TIMEOUT_MS} ms`)), TIMEOUT_MS); });
  return Promise.race([promise, timeout]).finally(() => clearTimeout(timer));
}

(async () => {
  let failed = 0;
  for (const t of tests) {
    try {
      await withTimeout(Promise.resolve().then(t.fn));
      console.log(`  ✓ ${t.name}`);
    } catch (e) {
      failed++;
      console.log(`  ✗ ${t.name}`);
      console.log(`    ${String(e && e.message).split('\n').join('\n    ')}`);
    }
  }
  console.log(`\nTests: ${failed} failed, ${tests.length - failed} passed, ${tests.length} total`);
  // Exit explicitly: a hung test may leave timers or promises behind.
  process.exit(failed ? 1 : 0);
})();

